// Turn a Slack question into one Gemini request containing every candidate's profile.
const event = $('Slack question').first().json;
const question = (event.text || '').replace(/<@[^>]+>/g, '').trim();
if (!question) throw new Error('Empty question');

const candidates = $('Get candidates').all().map(i => i.json).filter(c => c.id);
const roles = $('Get roles').all().map(i => i.json).filter(r => r.id);

const candidateList = candidates.map(c =>
  `[id ${c.id}] ${c.full_name} | ${c.headline} | ${c.location}\n` +
  `languages: ${(c.languages || []).join(', ')}\n` +
  `skills (years): ${c.skills}\n` +
  `CV text: ${(c.cv_text || c.summary || '').replace(/\s+/g, ' ').slice(0, 1500)}`
).join('\n\n');

const roleList = roles.length
  ? roles.map(r => `[role ${r.id}] ${r.title} for ${r.client_name}. Must-haves: ${(r.must_haves || []).join('; ')}. Nice-to-haves: ${(r.nice_to_haves || []).join('; ')}`).join('\n')
  : '(no open roles)';

const instructions = `You are a recruiting search assistant. A recruiter asks a question in plain English.
Answer ONLY from the candidate list below. Never invent a candidate, a skill, or a number.

How to answer:
1. Work out the hard requirements from the question (skills, minimum years, languages, certifications, etc.).
   If the question names one of the open roles, also use that role's must-haves as hard requirements.
   Set role_id to that role's id, or 0 if the question is not about a specific role.
2. Keep only candidates who meet EVERY hard requirement, using the "skills (years)" line and the CV text as evidence.
   "3+ years" means years >= 3. A language counts only if it is listed.
3. Score each kept candidate from 0 to 100:
   60 points for meeting all hard requirements,
   up to 25 more for experience beyond the minimum,
   up to 15 more for nice-to-haves or clearly relevant extras.
4. Return at most 5, best first. Fewer is fine. If nobody qualifies, return no matches and explain
   in no_match_reason what was missing (e.g. "Nobody has both 3+ years of GHL and Arabic. Closest: ...").
5. reason: exactly two short lines separated by "\\n". Line 1: why they fit, with the real numbers.
   Line 2: the main gap or risk, or a bonus. Under 25 words each.

Open roles:
${roleList}`;

const schema = {
  type: 'object',
  properties: {
    role_id: { type: 'integer' },
    matches: {
      type: 'array',
      items: {
        type: 'object',
        properties: { candidate_id: { type: 'integer' }, score: { type: 'integer' }, reason: { type: 'string' } },
        required: ['candidate_id', 'score', 'reason'],
        additionalProperties: false
      }
    },
    no_match_reason: { type: 'string' }
  },
  required: ['role_id', 'matches', 'no_match_reason'],
  additionalProperties: false
};

return [{
  json: {
    question: question,
    channel: event.channel,
    body: {
      model: 'gemini-3.5-flash-lite',
      system_instruction: instructions,
      input: [{ type: 'text', text: `Question: ${question}\n\nCandidates (${candidates.length}):\n\n${candidateList}` }],
      response_format: { type: 'text', mime_type: 'application/json', schema: schema }
    }
  }
}];

// Check Gemini's answer against the real database before showing it to anyone.
// Only candidates that exist in the database survive, and names and CV files come
// from the database, not from the AI, so every recommendation cites a real CV.
const reply = $input.first().json;
const req = $('Build search request').first().json;
const candidates = $('Get candidates').all().map(i => i.json).filter(c => c.id);
const roles = $('Get roles').all().map(i => i.json).filter(r => r.id);
const byId = new Map(candidates.map(c => [Number(c.id), c]));

let answer = null;
let problem = '';
try {
  if (reply.error) throw new Error(typeof reply.error === 'string' ? reply.error : (reply.error.description || reply.error.message || 'API error'));
  if (reply.status && reply.status !== 'completed') throw new Error('Gemini did not finish: ' + reply.status);
  const steps = reply.steps || [];
  const output = steps.filter(s => s.type === 'model_output').pop() || steps[steps.length - 1];
  const textPart = ((output && output.content) || []).find(c => c.type === 'text');
  answer = JSON.parse(textPart ? textPart.text : reply.output_text);
} catch (e) {
  problem = e.message;
}

const seen = new Set();
const matches = ((answer && answer.matches) || [])
  .filter(m => byId.has(Number(m.candidate_id)) && !seen.has(Number(m.candidate_id)) && seen.add(Number(m.candidate_id)))
  .map(m => {
    const c = byId.get(Number(m.candidate_id));
    return {
      candidate_id: Number(c.id),
      name: c.full_name,
      cv_file: c.cv_file_name,
      score: Math.max(0, Math.min(100, Math.round(m.score))),
      reason: String(m.reason || '').trim()
    };
  })
  .sort((a, b) => b.score - a.score)
  .slice(0, 5);

const role = roles.find(r => Number(r.id) === Number(answer && answer.role_id));

let text;
if (!answer) {
  text = `:warning: I couldn't answer "${req.question}" right now (${problem}). Please ask again in a minute.`;
} else if (!matches.length) {
  text = `:mag: *No good match* for "${req.question}".\n${answer.no_match_reason || 'Nobody in the CV database meets all the requirements.'}\nI won't suggest someone who doesn't fit.`;
} else {
  const lines = matches.map((m, i) =>
    `*${i + 1}. ${m.name}*: ${m.score}/100\n${m.reason.split('\n').map(l => '> ' + l).join('\n')}\n> :page_facing_up: ${m.cv_file}`);
  text = `:mag: *Top ${matches.length}* for "${req.question}"` +
    (role ? ` (role #${role.id}: ${role.title})` : '') + `\n\n` + lines.join('\n\n');
}

return [{
  json: {
    question: req.question,
    channel: req.channel,
    role_id: role ? Number(role.id) : 0,
    role_title: role ? role.title : '',
    matches: matches,
    candidate_ids: matches.map(m => m.candidate_id).join(','),
    shortlist_rows: role ? matches.map(m => ({ role_id: Number(role.id), candidate_id: m.candidate_id, score: m.score, reason: m.reason, source_cv: m.cv_file })) : [],
    text: text
  }
}];

